"""PayPal Orders v2 through the official PayPal Server SDK (generated by APIMatic).

Always uses the Sandbox environment. Without credentials the service runs in
"simulated" mode so the rest of the app can be demoed before keys are added.
"""

from __future__ import annotations

import asyncio
import json
import logging
import secrets
import string
from typing import Any

from paypalserversdk.configuration import Environment
from paypalserversdk.exceptions.api_exception import ApiException
from paypalserversdk.http.auth.o_auth_2 import ClientCredentialsAuthCredentials
from paypalserversdk.models.amount_with_breakdown import AmountWithBreakdown
from paypalserversdk.models.checkout_payment_intent import CheckoutPaymentIntent
from paypalserversdk.models.order_request import OrderRequest
from paypalserversdk.models.purchase_unit_request import PurchaseUnitRequest
from paypalserversdk.paypal_serversdk_client import PaypalServersdkClient

from .config import Settings

log = logging.getLogger("shoppilot.paypal")


class PayPalError(Exception):
    def __init__(self, message: str, status: int = 502):
        super().__init__(message)
        self.status = status


def _fake_id() -> str:
    alphabet = string.ascii_uppercase + string.digits
    return "".join(secrets.choice(alphabet) for _ in range(17))


def _friendly(err: Exception) -> PayPalError:
    text = getattr(getattr(err, "response", None), "text", "") or str(err)
    if "INSTRUMENT_DECLINED" in text:
        return PayPalError("PayPal declined that payment method. Please choose another one.", 422)
    if "ORDER_ALREADY_CAPTURED" in text:
        return PayPalError("This order was already paid.", 409)
    if "ORDER_NOT_APPROVED" in text:
        return PayPalError("The payment hasn't been approved in PayPal yet.", 422)
    if "invalid_client" in text or "Client Authentication failed" in text:
        return PayPalError("PayPal rejected the server credentials. Check PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET.", 502)
    log.warning("PayPal API error: %s", text[:500])
    return PayPalError("PayPal could not complete the request. Nothing was charged.", 502)


class PayPalService:
    def __init__(self, settings: Settings):
        self.client_id = settings.paypal_client_id
        self.mode = "sandbox" if settings.paypal_ready else "simulated"
        self.client: PaypalServersdkClient | None = None
        if self.mode == "sandbox":
            self.client = PaypalServersdkClient(
                client_credentials_auth_credentials=ClientCredentialsAuthCredentials(
                    o_auth_client_id=settings.paypal_client_id,
                    o_auth_client_secret=settings.paypal_client_secret,
                ),
                environment=Environment.SANDBOX,
                timeout=30,
            )
        log.info("PayPal mode: %s", self.mode)

    async def create_order(self, product: dict[str, Any], local_id: str) -> str:
        """Creates an order for exactly one product at the database price. Returns the PayPal order ID."""
        if not self.client:
            return _fake_id()
        body = OrderRequest(
            intent=CheckoutPaymentIntent.CAPTURE,
            purchase_units=[
                PurchaseUnitRequest(
                    reference_id=product["id"],
                    custom_id=local_id,
                    description=product["name"][:127],
                    amount=AmountWithBreakdown(currency_code="USD", value=f"{product['price']:.2f}"),
                )
            ],
        )
        try:
            resp = await asyncio.to_thread(
                self.client.orders.create_order,
                {"body": body, "paypal_request_id": local_id, "prefer": "return=minimal"},
            )
        except ApiException as e:
            raise _friendly(e) from e
        if not resp.is_success() or not getattr(resp.body, "id", None):
            raise _friendly(RuntimeError(getattr(resp, "text", "")))
        return resp.body.id

    async def capture_order(self, paypal_order_id: str) -> dict[str, Any]:
        """Captures an approved order. Returns status, capture ID, captured amount and the raw response."""
        if not self.client:
            await asyncio.sleep(0.6)
            return {"status": "COMPLETED", "captureId": _fake_id(), "amount": None, "currency": "USD", "raw": {"simulated": True}}
        try:
            resp = await asyncio.to_thread(
                self.client.orders.capture_order,
                {"id": paypal_order_id, "paypal_request_id": f"capture-{paypal_order_id}", "prefer": "return=representation"},
            )
        except ApiException as e:
            raise _friendly(e) from e
        if not resp.is_success():
            raise _friendly(RuntimeError(getattr(resp, "text", "")))
        try:
            raw = json.loads(resp.text) if getattr(resp, "text", None) else None
        except ValueError:
            raw = None
        captures = []
        for unit in getattr(resp.body, "purchase_units", None) or []:
            payments = getattr(unit, "payments", None)
            captures.extend(getattr(payments, "captures", None) or [])
        cap = captures[0] if captures else None
        return {
            "status": str(getattr(cap, "status", None) or getattr(resp.body, "status", "")),
            "captureId": getattr(cap, "id", None),
            "amount": float(cap.amount.value) if cap is not None and getattr(cap, "amount", None) else None,
            "currency": getattr(getattr(cap, "amount", None), "currency_code", "USD"),
            "raw": raw,
        }
